ERROR_TYPES = frozenset(('Refused', 'ValueError', 'FileNotFoundError', 'TimeoutError', 'TimeoutExpired', 'PermissionError', 'OSError', 'KeyError', 'TypeError'))

def details(error, phase):
    if phase not in PHASES:
        phase = 'source_admission'
    kind = type(error).__name__
    kind = kind if kind in ERROR_TYPES else 'OtherException'
    code = str(error) if kind == 'Refused' and (str(error) in FIXED_REASONS or config_reason(str(error))) else 'readonly_or_owned_fixed_failure'
    value = {'phase': phase, 'source_reason_code': code, 'error_type': kind, 'errno': error.errno if isinstance(error, OSError) and error.errno in (2, 5, 13, 22, 28, 32, 110, 111) else None}
    value.update(location(error))
    evidence = range_diagnostic.find(error)
    if evidence is not None:
        value['range_failure_evidence'] = evidence
    return value

def config_reason(code):
    import hashlib, json
    from pathlib import Path
    if type(code) is not str or ':' not in code:
        return False
    prefix, path = code.split(':', 1)
    if prefix not in ('type', 'unknown_or_missing_field', 'list', 'value'):
        return False
    try:
        raw = Path(__file__).with_name('OFFICIAL_MERGED_BASELINE.json').read_bytes()
    except OSError:
        return False
    if len(raw) > 65536 or hashlib.sha256(raw).hexdigest() != '6bb755798fafa04c6a66bc7dca67688f6a3102b8f39c370d4461db6737f35676':
        return False
    types = {}

    def walk(v, p):
        types[p] = type(v)
        if isinstance(v, dict):
            for k, x in v.items():
                walk(x, p + '.' + k)
        elif isinstance(v, list):
            for i, x in enumerate(v):
                walk(x, p + '.' + str(i))
    walk(json.loads(raw), 'root')
    if path not in types:
        return False
    return prefix == 'type' or (prefix == 'unknown_or_missing_field' and types[path] is dict) or (prefix == 'list' and types[path] is list) or (prefix == 'value' and types[path] not in (dict, list))

def location(error):
    out = {'source_location': None, 'proc_path': None}
    allowed = APPROVED_TRACE_FILES
    if type(allowed) in (tuple, list):
        tb = error.__traceback__
        while tb is not None:
            code = tb.tb_frame.f_code
            if code.co_filename in allowed and type(tb.tb_lineno) is int and (0 < tb.tb_lineno < 100000) and re.fullmatch('[A-Za-z_][A-Za-z0-9_<>]{0,100}', code.co_name):
                out['source_location'] = {'source': code.co_filename, 'function': code.co_name, 'line': tb.tb_lineno}
            tb = tb.tb_next
    name = error.filename if isinstance(error, OSError) else None
    if type(name) is str and len(name) <= 128 and re.fullmatch('/proc/[0-9]{1,10}/(?:stat|exe|environ|cgroup|fd/[0-9]{1,10})', name):
        out['proc_path'] = name
    return out
